CohStatus coh_runtime_graph_sources(const CohRuntimeGraph*g,CohBytes*c,CohBytes*s){(void)g;*c=(CohBytes){catalog,8};*s=(CohBytes){snapshot,8};return COH_OK;}
CohStatus coh_runtime_graph_binding(const CohRuntimeGraph*g,CohRuntimeGraphBinding*out){*out=g->binding;return COH_OK;}
CohStatus coh_runtime_graph_report(const CohRuntimeGraph*g,CohRuntimeGraphReport*out){*out=g->report;return COH_OK;}
CohStatus coh_runtime_graph_node(const CohRuntimeGraph*g,uint32_t i,CohRuntimeGraphNode*out){if(i>=4)return COH_NOT_FOUND;*out=g->nodes[i];return COH_OK;}
CohStatus coh_runtime_graph_child(const CohRuntimeGraph*g,uint32_t i,CohRuntimeGraphChild*out){if(i>=4)return COH_NOT_FOUND;*out=g->edges[i];return COH_OK;}
CohStatus coh_runtime_graph_root(const CohRuntimeGraph*g,uint32_t i,CohRuntimeGraphRoot*out){if(i>=2)return COH_NOT_FOUND;*out=g->roots[i];return COH_OK;}
CohStatus coh_resource_join_identity(const CohResourceJoin*j,CohResourceJoinIdentity*out){*out=j->identity;return COH_OK;}
CohStatus coh_resource_join_sources(const CohResourceJoin*j,const CohResourceSource**out,size_t*count,CohResourceBinding*b){*out=j->sources;*count=j->count;*b=j->identity.pins.resource;return COH_OK;}
CohStatus coh_resource_join_node(const CohResourceJoin*j,uint32_t row,uint32_t*out){if(row>=j->count)return COH_NOT_FOUND;*out=j->map[row];return COH_OK;}
CohStatus coh_resource_join_retain(CohResourceJoin*j){if(j->refs==UINT32_MAX)return COH_LIMIT;j->refs++;return COH_OK;}
void coh_resource_join_free(CohResourceJoin*j){CHECK(j->refs);j->refs--;}
