void*__wrap_malloc(size_t n){calls++;if(calls==fail_at)return NULL;void*p=__real_malloc(n);live+=p!=NULL;return p;}
void*__wrap_calloc(size_t n,size_t s){calls++;if(calls==fail_at)return NULL;void*p=__real_calloc(n,s);live+=p!=NULL;return p;}
void __wrap_free(void*p){if(p){CHECK(live);live--;}__real_free(p);}
